const GIL = "import sys\nimport threading\nimport time\n\n\ndef count(n):\n    while n:\n        n -= 1\n\n\nN = 20_000_000\nprint(\"GIL enabled:\", sys._is_gil_enabled())\n\nstart = time.perf_counter()\ncount(N)\ncount(N)\nprint(f\"one after another: {time.perf_counter() - start:.2f} s\")\n\nstart = time.perf_counter()\nthreads = [threading.Thread(target=count, args=(N,)) for _ in range(2)]\nfor t in threads:\n    t.start()\nfor t in threads:\n    t.join()\nprint(f\"two threads:       {time.perf_counter() - start:.2f} s\")"
const DEFAULT = "$ python gil.py\nGIL enabled: True\none after another: 0.57 s\ntwo threads:       0.71 s"
const FREE = "$ python3.14t gil.py\nGIL enabled: False\none after another: 0.57 s\ntwo threads:       0.37 s"

